"use strict";

// Our calf and ewe maquette pigments baked onto a 4 × 5 UV sheet.
// R and G of the slip map carry sculpted relief and local roughness.
// Embedded WebPs also decode on file:// during offline play.
const pastureSlip = (() => {
  function loadMap(data, srgb) {
    const image = new Image();
    const map = new THREE.Texture(image);
    if (srgb) map.colorSpace = THREE.SRGBColorSpace;
    map.anisotropy = 2;
    const ready = new Promise((resolve, reject) => {
      image.onload = () => { map.needsUpdate = true; resolve(); };
      image.onerror = () => reject(new Error("Unable to decode the pasture clay atlas"));
    });
    image.src = "data:image/webp;base64," + data;
    return {map, ready};
  }
  const pigment = loadMap("", true);
  const slip = loadMap("", false);
  const material = new THREE.MeshStandardMaterial({
    name: "Paddock clay · rubbed earth pigments", map: pigment.map, vertexColors: true,
    bumpMap: slip.map, bumpScale: .006, roughnessMap: slip.map, roughness: 1,
    metalness: 0
  });
  return {material, ready: Promise.all([pigment.ready, slip.ready])};
})();
function createPastureCoatMaterial() { return pastureSlip.material; }
